// Hanken Grotesk 300 (fontTools, wght 300): tabular figures 0.56em, "$" 0.553,
// "." and "," 0.24; cap height 0.697. Instrument Serif italic: F r o m.
const HANKEN: Record<string, number> = { $: 0.553, ".": 0.24, ",": 0.24 };
const DIGIT = 0.56;
const CAP = 0.697;
const TRACK = -0.02;
const SERIF: Record<string, number> = {
  F: 0.411,
  r: 0.368,
  o: 0.414,
  m: 0.745,
  " ": 0.17,
};

const adv = (ch: string) => (isDigit(ch) ? DIGIT : (HANKEN[ch] ?? 0.58));

function layoutPrice(s: string) {
  const glyphs: Array<{ ch: string; x: number; w: number }> = [];
  let x = 0;
  for (const ch of Array.from(s)) {
    glyphs.push({ ch, x, w: adv(ch) });
    x += adv(ch) + TRACK;
  }
  return { glyphs, width: Math.max(0, x - TRACK) };
}

const serifWidth = (s: string) =>
  Array.from(s).reduce((w, ch) => w + (SERIF[ch] ?? 0.42), 0);

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_REEL = Easing.bezier(0.12, 0.6, 0.18, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// Beat sheet (30fps, speed 1):
//   0–22   the old price reels in at hero size beside the serif lead-in
//  22–34   a clean line strikes it through
//  34–52   it steps aside: shrinks, greys out, slides left
//  47–73   the new price reels spin into the hero slot (digits 3 frames apart)
//  69–91   the halo gradient sweeps across it as the last reel lands
//  71–99   note and availability rise in; poster holds to the end

// gradients.sh "halo" (bg #030306): #fff4ec #ffb36b #e2457a #3d4dff.
const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F5F4F1",
    muted: "#7C7B81",
    hair: "rgba(245,244,241,0.14)",
    halo: ["#FFF4EC", "#FFB36B", "#E2457A", "#3D4DFF"],
    stops: [0, 0.3, 0.64, 1],
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#8A8883",
    hair: "rgba(18,18,20,0.12)",
    halo: ["#F08A2C", "#E2457A", "#9B47C9", "#3D4DFF"],
    stops: [0, 0.34, 0.66, 1],
  },
} as const;

/** One reel position: spins `turns` digits and lands on `digit`. */
function reel(
  t: number,
  start: number,
  len: number,
  digit: number,
  turns: number,
) {
  const k = EASE_REEL(Math.max(0, Math.min(1, (t - start) / len)));
  return digit - turns * (1 - k);
}

const midway = (p: number) => p > 0 && p < 1;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function PriceSlate(props: PriceSlateProps) {
  const {
    price = "$0",
    was = "$29",
    lead = "From",
    note = "per seat · billed yearly",
    availability = "Available today",
    product = "Pro",
    name = "remocn",
    logo,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    turns = 13,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    priceSlateTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const leadEl = tl.get("lead");
  const oldEl = tl.get("old");
  const strikeEl = tl.get("strike");
  const asideEl = tl.get("aside");
  const newEl = tl.get("new");
  const haloEl = tl.get("halo");
  const u = H / 720;
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const newL = layoutPrice(price);
  const oldL = layoutPrice(was);
  const leadW = serifWidth(lead);

  // Final line: lead (S) · old price (S, struck) · new price (P), centred.
  const ratio = 0.4;
  const gapA = 0.26; // in S units, between lead and old price
  const gapB = 0.34; // in S units, between old price and new price
  const finalEm = (leadW + gapA + oldL.width + gapB) * ratio + newL.width;
  const P = Math.min(H * 0.4, (W * 0.78) / finalEm);
  const S = P * ratio;
  const baseline = H * 0.62;

  // Opening line: lead (S) · old price (P), centred.
  const openW = (leadW + gapA) * S + oldL.width * P;
  const finalW = finalEm * P;
  const leadX0 = (W - openW) / 2;
  const oldX0 = leadX0 + (leadW + gapA) * S;
  const leadX1 = (W - finalW) / 2;
  const oldX1 = leadX1 + (leadW + gapA) * S;
  const newX = oldX1 + (oldL.width + gapB) * S;

  const m = EASE_IO(
    Math.max(0, Math.min(1, (t - asideEl.start) / asideEl.length)),
  );
  const leadX = leadX0 + (leadX1 - leadX0) * m;
  const oldX = oldX0 + (oldX1 - oldX0) * m;
  const oldSize = P + (S - P) * m;
  const oldColor = interpolateColors(m, [0, 1], [fg, p.muted]);

  const leadIn = interpolate(t, [leadEl.start, leadEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const strike = interpolate(t, [strikeEl.start, strikeEl.end], [0, 1], {
    ...CLAMP,
    easing: Easing.bezier(0.6, 0, 0.25, 1),
  });
  // the halo sweeps in as the last reel lands
  const sweep = interpolate(t, [haloEl.start, haloEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rise = (id: "brand" | "note" | "availability") => {
    const e = tl.get(id);
    return interpolate(t, [e.start, e.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  const drift = interpolate(t, [0, 130], [0, 1], CLAMP);

  /** Renders a price on reels; returns elements in user space. */
  const renderPrice = (
    L: ReturnType<typeof layoutPrice>,
    x0: number,
    size: number,
    e: ResolvedElement<PriceSlateElementId>,
    turns: number,
    key: string,
    only: "digits" | "marks",
  ) => {
    const step = (CAP + 0.26) * size;
    let di = 0;
    return L.glyphs.map((g, i) => {
      const gx = x0 + (g.x + g.w / 2) * size;
      if (!isDigit(g.ch)) {
        if (only === "digits") return null;
        // the old price's marks are there from the first frame; the new
        // price's wait for the old one to clear the slot
        const k = interpolate(
          t,
          [
            e.start + e.beat("lag") + i * e.beat("markStep"),
            e.start + e.beat("lag") + e.beat("markIn") + i * e.beat("markStep"),
          ],
          [0, 1],
          {
            ...CLAMP,
            easing: EASE_OUT,
          },
        );
        return (
          <text
            key={`${key}${i}`}
            x={gx}
            y={baseline + (1 - k) * 0.35 * size}
            opacity={k}
          >
            {g.ch}
          </text>
        );
      }
      const d = Number(g.ch);
      const s0 = e.start + di * e.beat("stagger");
      const extra = turns + di * 2;
      di++;
      if (only === "marks") return null;
      const len = e.beat("reel") + di * e.beat("spin");
      const pos = reel(t, s0, len, d, extra);
      const v = Math.abs(
        reel(t + 0.5, s0, len, d, extra) - reel(t - 0.5, s0, len, d, extra),
      );
      const base = Math.floor(pos);
      const f = pos - base;
      const show = interpolate(
        t,
        [s0 + e.beat("showAt"), s0 + e.beat("showEnd")],
        [0, 1],
        CLAMP,
      );
      const sd = Math.min(0.06, v * 0.05) * size;
      const digit = (n: number) => ((n % 10) + 10) % 10;
      return (
        <g
          key={`${key}${i}`}
          opacity={show}
          transform={`translate(0 ${-f * step})`}
        >
          <g filter={sd > 0.05 ? `url(#${uid}b${key}${i})` : undefined}>
            <text x={gx} y={baseline}>
              {digit(base)}
            </text>
            {f > 0.001 ? (
              <text x={gx} y={baseline + step}>
                {digit(base + 1)}
              </text>
            ) : null}
          </g>
          <filter
            id={`${uid}b${key}${i}`}
            filterUnits="userSpaceOnUse"
            x={0}
            y={0}
            width={W}
            height={H}
          >
            <feGaussianBlur stdDeviation={`0 ${sd.toFixed(2)}`} />
          </filter>
        </g>
      );
    });
  };

  // Every vertical px the SVG text travels at time `tt` (lead lift, old price
  // size, mark lifts, reel offsets), mirroring renderPrice, so the tilt on the
  // <svg> stays on exactly while some glyph run still moves.
  const svgTravel = (tt: number) => {
    const mm = EASE_IO(
      Math.max(0, Math.min(1, (tt - asideEl.start) / asideEl.length)),
    );
    const size = P + (S - P) * mm;
    const li = interpolate(tt, [leadEl.start, leadEl.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const out = [size, (1 - li) * 0.2 * S];
    const prices = [
      { L: oldL, sz: size, e: oldEl, n: 7 },
      { L: newL, sz: P, e: newEl, n: turns },
    ];
    for (const { L, sz, e, n } of prices) {
      const step = (CAP + 0.26) * sz;
      let di = 0;
      L.glyphs.forEach((g, i) => {
        if (!isDigit(g.ch)) {
          const k = interpolate(
            tt,
            [
              e.start + e.beat("lag") + i * e.beat("markStep"),
              e.start +
                e.beat("lag") +
                e.beat("markIn") +
                i * e.beat("markStep"),
            ],
            [0, 1],
            { ...CLAMP, easing: EASE_OUT },
          );
          out.push((1 - k) * 0.35 * sz);
          return;
        }
        const s0 = e.start + di * e.beat("stagger");
        const extra = n + di * 2;
        di++;
        out.push(
          reel(
            tt,
            s0,
            e.beat("reel") + di * e.beat("spin"),
            Number(g.ch),
            extra,
          ) * step,
        );
      });
    }
    return out;
  };
  const travelNow = svgTravel(t);
  const travelPrev = svgTravel(t - speed);
  const travelNext = svgTravel(t + speed);
  const svgMoving = travelNow.some(
    (v, i) =>
      Math.abs(v - travelPrev[i]) > 1e-3 || Math.abs(travelNext[i] - v) > 1e-3,
  );

  const newCap = CAP * P;
  const oldCap = CAP * oldSize;
  const strikeY = baseline - oldCap * 0.44;
  const strikeX0 = oldX - 0.05 * oldSize;
  const strikeX1 = oldX + (oldL.width + 0.05) * oldSize;
  const strikeT = Math.max(1.5 * u, 0.034 * oldSize);

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{
            position: "absolute",
            inset: 0,
            // the SVG paints no background, so a tilt shows no seam
            transform: glide(svgMoving).trim(),
          }}
          role="img"
          aria-label={`${lead} ${price}, was ${was}`}
        >
          <defs>
            <linearGradient id={`${uid}feather`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="0" stopColor="#fff" stopOpacity={0} />
              <stop offset="0.14" stopColor="#fff" />
              <stop offset="0.86" stopColor="#fff" />
              <stop offset="1" stopColor="#fff" stopOpacity={0} />
            </linearGradient>
            {/* reel windows: one for the old price (it shrinks), one for the new */}
            <mask
              id={`${uid}winOld`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect
                x={0}
                y={baseline - oldCap - 0.14 * oldSize}
                width={W}
                height={oldCap + 0.28 * oldSize}
                fill={`url(#${uid}feather)`}
              />
            </mask>
            <mask
              id={`${uid}winNew`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect
                x={0}
                y={baseline - newCap - 0.14 * P}
                width={W}
                height={newCap + 0.28 * P}
                fill={`url(#${uid}feather)`}
              />
            </mask>
            <linearGradient
              id={`${uid}halo`}
              gradientUnits="userSpaceOnUse"
              x1={newX - newL.width * P * (0.1 - 0.12 * drift)}
              y1={baseline - newCap}
              x2={newX + newL.width * P * (1.05 + 0.1 * drift)}
              y2={baseline}
            >
              {p.halo.map((c, i) => (
                <stop key={c} offset={p.stops[i]} stopColor={c} />
              ))}
            </linearGradient>
            {/* the gradient sweeps across the landed price, left to right */}
            <linearGradient
              id={`${uid}wipe`}
              gradientUnits="userSpaceOnUse"
              x1={newX - 0.4 * P + sweep * (newL.width * P + 0.8 * P)}
              y1={0}
              x2={newX + sweep * (newL.width * P + 0.8 * P)}
              y2={0}
            >
              <stop offset="0" stopColor="#fff" />
              <stop offset="1" stopColor="#fff" stopOpacity={0} />
            </linearGradient>
            <mask
              id={`${uid}sweep`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect width={W} height={H} fill={`url(#${uid}wipe)`} />
            </mask>
            <linearGradient
              id={`${uid}wipeInv`}
              gradientUnits="userSpaceOnUse"
              x1={newX - 0.4 * P + sweep * (newL.width * P + 0.8 * P)}
              y1={0}
              x2={newX + sweep * (newL.width * P + 0.8 * P)}
              y2={0}
            >
              <stop offset="0" stopColor="#fff" stopOpacity={0} />
              <stop offset="1" stopColor="#fff" />
            </linearGradient>
            <mask
              id={`${uid}ink`}
              maskUnits="userSpaceOnUse"
              x={0}
              y={0}
              width={W}
              height={H}
            >
              <rect width={W} height={H} fill={`url(#${uid}wipeInv)`} />
            </mask>
          </defs>

          {/* lead-in */}
          <text
            x={leadX}
            y={baseline}
            fontFamily={serif}
            fontStyle="italic"
            fontWeight={400}
            fontSize={S}
            fill={fg}
            opacity={leadIn}
            transform={`translate(0 ${(1 - leadIn) * 0.2 * S})`}
          >
            {lead}
          </text>

          {/* old price, then its strike */}
          <g
            fontFamily={fontFamily}
            fontWeight={300}
            fontSize={oldSize}
            textAnchor="middle"
            fill={oldColor}
            style={{ fontVariantNumeric: "tabular-nums" }}
          >
            <g mask={`url(#${uid}winOld)`}>
              {renderPrice(oldL, oldX, oldSize, oldEl, 7, "o", "digits")}
            </g>
            {renderPrice(oldL, oldX, oldSize, oldEl, 7, "o", "marks")}
          </g>
          <line
            x1={strikeX0}
            x2={strikeX0 + (strikeX1 - strikeX0) * strike}
            y1={strikeY}
            y2={strikeY}
            stroke={interpolateColors(m, [0, 1], [fg, p.muted])}
            strokeWidth={strikeT}
            strokeLinecap="round"
            opacity={strike > 0 ? 1 : 0}
          />

          {/* new price: ink while it rolls, halo gradient once it lands */}
          <g
            fontFamily={fontFamily}
            fontWeight={300}
            fontSize={P}
            textAnchor="middle"
            fill={fg}
            style={{ fontVariantNumeric: "tabular-nums" }}
            mask={sweep > 0 ? `url(#${uid}ink)` : undefined}
          >
            <g mask={`url(#${uid}winNew)`}>
              {renderPrice(newL, newX, P, newEl, turns, "n", "digits")}
            </g>
            {renderPrice(newL, newX, P, newEl, turns, "n", "marks")}
          </g>
          <g
            mask={`url(#${uid}sweep)`}
            fontFamily={fontFamily}
            fontWeight={300}
            fontSize={P}
            textAnchor="middle"
            fill={`url(#${uid}halo)`}
            style={{ fontVariantNumeric: "tabular-nums" }}
            opacity={sweep > 0 ? 1 : 0}
          >
            {newL.glyphs.map((g) => (
              <text
                key={`h${g.x}${g.ch}`}
                x={newX + (g.x + g.w / 2) * P}
                y={baseline}
              >
                {g.ch}
              </text>
            ))}
          </g>
        </svg>

        {/* brand + product, top */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: H * 0.115,
            display: "flex",
            justifyContent: "center",
            alignItems: "baseline",
            gap: 12 * u,
            opacity: rise("brand"),
            transform: `translateY(${(1 - rise("brand")) * 10 * u}px)${glide(midway(rise("brand")))}`,
            lineHeight: 1,
          }}
        >
          {logo ??
            (name.trim().toLowerCase() === "remocn" ? (
              <RemocnLogo fontSize={34 * u} color={fg} />
            ) : (
              <span
                style={{
                  fontFamily,
                  fontWeight: 400,
                  fontSize: 34 * u,
                  letterSpacing: "-0.02em",
                  color: fg,
                }}
              >
                {name}
              </span>
            ))}
          {product ? (
            <span
              style={{
                fontFamily,
                fontWeight: 300,
                fontSize: 34 * u,
                letterSpacing: "-0.02em",
                color: fg,
              }}
            >
              {product}
            </span>
          ) : null}
        </div>

        {/* note under the price */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: baseline + 0.2 * P,
            textAlign: "center",
            fontFamily,
            fontWeight: 400,
            fontSize: 30 * u,
            letterSpacing: "-0.01em",
            color: p.muted,
            opacity: rise("note"),
            transform: `translateY(${(1 - rise("note")) * 12 * u}px)${glide(midway(rise("note")))}`,
            lineHeight: 1,
          }}
        >
          {note}
        </div>

        {/* availability */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: H * 0.855,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            gap: 12 * u,
            fontFamily,
            fontWeight: 400,
            fontSize: 24 * u,
            letterSpacing: "-0.005em",
            color: fg,
            opacity: rise("availability"),
            transform: `translateY(${(1 - rise("availability")) * 12 * u}px)${glide(midway(rise("availability")))}`,
            lineHeight: 1,
          }}
        >
          <div
            style={{
              width: 8 * u,
              height: 8 * u,
              borderRadius: 99,
              background: accent,
            }}
          />
          {availability}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}
